const msgId = $json.msg_id;
const mensagem = $json.mensagem;

const rawMsg = ($('Webhook').first().json.body && $('Webhook').first().json.body.data && $('Webhook').first().json.body.data.message) || {};
const hasMedia = !!(rawMsg.audioMessage || rawMsg.imageMessage || rawMsg.documentMessage);

if ((!mensagem || mensagem.trim() === '') && !hasMedia) {
  return [];
}

if (!msgId) {
  return [$input.first()];
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedMsgIds) staticData.processedMsgIds = [];

if (staticData.processedMsgIds.includes(msgId)) {
  // Mesma mensagem do WhatsApp reentregue pelo webhook - ignorar
  return [];
}

staticData.processedMsgIds.push(msgId);
if (staticData.processedMsgIds.length > 200) {
  staticData.processedMsgIds = staticData.processedMsgIds.slice(-200);
}

return [$input.first()];

const dados = $('Montar Contexto').first().json;
const agentOut = $json;

const resposta_bruta = agentOut.output || '';
const steps = Array.isArray(agentOut.intermediateSteps) ? agentOut.intermediateSteps : [];
const confirmStep = steps.find(s => s.action?.tool === 'confirmar_pedido');
const confirmar_pedido = !!confirmStep;
const produto = confirmStep?.action?.toolInput?.produto ?? null;
const endereco = confirmStep?.action?.toolInput?.endereco ?? null;
const pagamento = confirmStep?.action?.toolInput?.pagamento ?? null;
const nome_cliente = confirmStep?.action?.toolInput?.nome_cliente ?? null;

let resposta_limpa = resposta_bruta;

if (confirmar_pedido) {
  try {
    const SUPA_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNsY3l5b2d0dnlncGVoZ2NtZXlqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4MDA4NTQ3NCwiZXhwIjoyMDk1NjYxNDc0fQ.XizutisZ4syhlUMlTRisVg1J8jFNNrZ9bF54ntF4B4M';
    const headers = { apikey: SUPA_KEY, Authorization: 'Bearer ' + SUPA_KEY };

    const regras = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://clcyyogtvygpehgcmeyj.supabase.co/rest/v1/promocoes_gas?negocio_id=eq.' + dados.negocio_id + '&tipo=eq.fidelidade&status=eq.ativa&select=regra_fidelidade_pedidos,regra_fidelidade_recompensa&order=criado_em.desc&limit=1',
      headers,
      json: true,
    });

    if (Array.isArray(regras) && regras.length > 0) {
      const N = parseInt(regras[0].regra_fidelidade_pedidos, 10);
      const clienteRows = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://clcyyogtvygpehgcmeyj.supabase.co/rest/v1/dados_clientes_gas?negocio_id=eq.' + dados.negocio_id + '&remote_jid=eq.' + encodeURIComponent(dados.remoteJid) + '&select=total_pedidos',
        headers,
        json: true,
      });
      const totalAnterior = (Array.isArray(clienteRows) && clienteRows[0]?.total_pedidos) || 0;
      const numeroPedidoAtual = totalAnterior + 1;

      if (N > 0 && numeroPedidoAtual % N === 0) {
        resposta_limpa = resposta_limpa + ' E boa noticia: esse foi seu ' + numeroPedidoAtual + 'o pedido, voce ganhou ' + regras[0].regra_fidelidade_recompensa + '! 🎉';
      }
    }
  } catch (e) {}
}

let nova_etapa = dados.etapa;
if (confirmar_pedido) {
  nova_etapa = 'despachado';
} else if (dados.etapa === 'inicio' && dados.mensagem) {
  nova_etapa = 'aguardando_produto';
} else if (dados.etapa === 'aguardando_produto') {
  nova_etapa = 'aguardando_endereco';
} else if (dados.etapa === 'aguardando_endereco') {
  nova_etapa = 'confirmando_pedido';
}

return [{
  json: {
    ...dados,
    resposta_limpa,
    confirmar_pedido,
    produto,
    endereco,
    pagamento,
    nome_cliente,
    nova_etapa
  }
}];

const dados = $('Processar Resposta Agent').first().json;
const geo = $json;
const loc = geo.results && geo.results[0] && geo.results[0].geometry && geo.results[0].geometry.location;

return [{
  json: {
    ...dados,
    lat: loc ? loc.lat : null,
    long: loc ? loc.lng : null
  }
}];

const filtro = $('Filtrar e Extrair').first().json;
const negocio = $json; // saida de Carregar Dados Negocio

const text = (filtro.mensagem || '').trim();
const fromMe = filtro.fromMe === true;

const digits = v => (v || '').toString().replace(/\D/g, '');
const telefoneChat = digits(filtro.remoteJid);
const telefoneAdmin = digits(negocio.telefone_admin);

let acao = 'cliente_falou';

if (fromMe) {
  const ehComando = text.startsWith('#');
  const ehChatDono = telefoneAdmin && telefoneChat && telefoneChat.endsWith(telefoneAdmin.slice(-8));
  if (ehComando && ehChatDono) {
    acao = 'comando_proprietario';
  } else {
    acao = 'humano_falou';
  }
}

return [{ json: { ...negocio, _acao: acao } }];

const negocio = $('Carregar Dados Negocio').first().json;
const filtro = $('Filtrar e Extrair').first().json;

let mensagemFinal = filtro.mensagem || '';

try {
  const audio = $('Transcrever Audio GAS').first().json;
  if (audio && audio.text) mensagemFinal = audio.text.trim();
} catch (e) {}

try {
  const imagem = $('Analisar Imagem GAS').first().json;
  const desc = imagem?.content || (imagem?.message && imagem.message.content) || imagem?.text || '';
  if (desc) mensagemFinal = '[Imagem enviada pelo cliente] ' + String(desc).trim();
} catch (e) {}

try {
  const doc = $('Extrair Texto Documento GAS').first().json;
  if (doc && doc.text) mensagemFinal = '[Documento enviado pelo cliente] ' + String(doc.text).trim();
} catch (e) {}

return [{ json: { ...negocio, mensagem: mensagemFinal, msg_id: filtro.msg_id } }];

const filtro = $('Filtrar e Extrair').first().json;
const negocio = $('Carregar Dados Negocio').first().json;
const texto = (filtro.mensagem || '').toLowerCase();

const hoje = new Date();
let inicio, fim, periodoTexto;

const matchDatas = texto.match(/(\d{2}\/\d{2}\/\d{4})\s*(?:ate|até|-|a)\s*(\d{2}\/\d{2}\/\d{4})/);

if (matchDatas) {
  const [, di, df] = matchDatas;
  const [d1, m1, y1] = di.split('/');
  const [d2, m2, y2] = df.split('/');
  inicio = new Date(`${y1}-${m1}-${d1}T00:00:00`);
  fim = new Date(`${y2}-${m2}-${d2}T23:59:59`);
  periodoTexto = `${di} a ${df}`;
} else if (texto.includes('semana')) {
  inicio = new Date(hoje); inicio.setDate(inicio.getDate() - 7);
  fim = hoje;
  periodoTexto = 'ultimos 7 dias';
} else if (texto.includes('mes') || texto.includes('mês')) {
  inicio = new Date(hoje.getFullYear(), hoje.getMonth(), 1);
  fim = hoje;
  periodoTexto = 'mes atual';
} else {
  inicio = new Date(hoje); inicio.setHours(0, 0, 0, 0);
  fim = hoje;
  periodoTexto = 'hoje';
}

return [{
  json: {
    negocio_id: negocio.id,
    nome_loja: negocio.nome,
    instancia: negocio.instancia_whatsapp,
    telefone_admin: negocio.telefone_admin,
    dataInicio: inicio.toISOString(),
    dataFim: fim.toISOString(),
    periodoTexto,
  },
}];

const loja = $('Parsear Periodo Relatorio GAS').first().json;
const pedidos = $('Buscar Pedidos Periodo GAS').all().map(i => i.json);
const entregadores = $('Buscar Entregadores Loja Relatorio GAS').all().map(i => i.json);

if (!pedidos || pedidos.length === 0) {
  return [{
    json: {
      telefone_admin: loja.telefone_admin,
      instancia: loja.instancia,
      mensagem: `Relatorio ${loja.nome_loja} - ${loja.periodoTexto}\n\nNenhum pedido no periodo.`,
    },
  }];
}

const porProduto = {};
pedidos.forEach(p => { const prod = p.produto_nome ?? 'Nao informado'; porProduto[prod] = (porProduto[prod] ?? 0) + 1; });

const porEntregador = {};
pedidos.forEach(p => {
  if (p.entregador_id) {
    const ent = entregadores.find(e => e.id === p.entregador_id);
    const nome = ent?.nome ?? 'Entregador ' + p.entregador_id;
    porEntregador[nome] = (porEntregador[nome] ?? 0) + 1;
  }
});

const despachados = pedidos.filter(p => p.status === 'despachado').length;
const entregues = pedidos.filter(p => p.status === 'entregue').length;
const cancelados = pedidos.filter(p => p.status === 'cancelado').length;
const faturamento = pedidos.reduce((acc, p) => acc + (parseFloat(p.valor_total) || 0), 0);

const produtosTexto = Object.entries(porProduto).map(([n, q]) => `   - ${n}: ${q}`).join('\n');
const entregadoresTexto = Object.entries(porEntregador).map(([n, q]) => `   - ${n}: ${q}`).join('\n');

const mensagem = `Relatorio ${loja.nome_loja}
Periodo: ${loja.periodoTexto}

Total de pedidos: ${pedidos.length}

Por produto:
${produtosTexto}

Por entregador:
${entregadoresTexto || '   - Nao informado'}

Status:
   - Despachados: ${despachados}
   - Entregues: ${entregues}
   - Cancelados: ${cancelados}

Faturamento estimado: R$${faturamento.toFixed(2)}`;

return [{ json: { telefone_admin: loja.telefone_admin, instancia: loja.instancia, mensagem } }];

const negocio = $('Carregar Dados Negocio').first().json;
let url = 'https://clcyyogtvygpehgcmeyj.supabase.co/rest/v1/pedidos_gas?negocio_id=eq.' + negocio.id + '&select=cliente_nome,cliente_telefone,endereco,produto_nome,forma_pagamento,valor_total,status,criado_em&order=criado_em.desc&limit=15';

if (typeof termo === 'string' && termo.trim() !== '') {
  const t = encodeURIComponent(termo.trim());
  url += '&or=(cliente_nome.ilike.*' + t + '*,cliente_telefone.ilike.*' + t + '*)';
}

const resposta = await this.helpers.httpRequest({
  method: 'GET',
  url,
  headers: {
    apikey: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNsY3l5b2d0dnlncGVoZ2NtZXlqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4MDA4NTQ3NCwiZXhwIjoyMDk1NjYxNDc0fQ.XizutisZ4syhlUMlTRisVg1J8jFNNrZ9bF54ntF4B4M',
    Authorization: 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNsY3l5b2d0dnlncGVoZ2NtZXlqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4MDA4NTQ3NCwiZXhwIjoyMDk1NjYxNDc0fQ.XizutisZ4syhlUMlTRisVg1J8jFNNrZ9bF54ntF4B4M',
  },
  json: true,
});

return JSON.stringify(resposta);

const negocio = $('Carregar Dados Negocio').first().json;
const out = $json.output || 'Nao consegui buscar essa informacao agora.';
return [{ json: { telefone_admin: negocio.telefone_admin, instancia: negocio.instancia_whatsapp, mensagem: out } }];

const negocio = $json; // saida de Carregar Dados Negocio
const filtro = $('Filtrar e Extrair').first().json;

const digits = v => (v || '').toString().replace(/\D/g, '');
const remetente = digits(filtro.remoteJid);

const textoLower = (filtro.mensagem || '').toLowerCase();
const frasesBot = [
  'novo pedido!',
  'atendente virtual',
  'upvia automa',
  'seu pedido est',
  'para organizar seu pedido',
  'confirmar alguns dados',
  'nome completo e um telefone',
  'maps.google.com'
];
const pareceBot = frasesBot.some(f => textoLower.includes(f));

// Se o texto nao parece resposta de bot, nem precisa gastar uma query - segue direto.
if (!pareceBot) {
  return [{ json: negocio }];
}

let entregadores = [];
try {
  const resposta = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://clcyyogtvygpehgcmeyj.supabase.co/rest/v1/entregadores_gas?negocio_id=eq.' + negocio.id + '&select=jid_whatsapp',
    headers: {
      apikey: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNsY3l5b2d0dnlncGVoZ2NtZXlqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4MDA4NTQ3NCwiZXhwIjoyMDk1NjYxNDc0fQ.XizutisZ4syhlUMlTRisVg1J8jFNNrZ9bF54ntF4B4M',
      Authorization: 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNsY3l5b2d0dnlncGVoZ2NtZXlqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4MDA4NTQ3NCwiZXhwIjoyMDk1NjYxNDc0fQ.XizutisZ4syhlUMlTRisVg1J8jFNNrZ9bF54ntF4B4M',
    },
    json: true,
  });
  entregadores = Array.isArray(resposta) ? resposta : [];
} catch (e) {
  entregadores = [];
}

const ehEntregador = entregadores.some(e => {
  const d = digits(e.jid_whatsapp);
  return d && remetente && (d.endsWith(remetente.slice(-8)) || remetente.endsWith(d.slice(-8)));
});

const ehDono = digits(negocio.telefone_admin) && remetente && remetente.endsWith(digits(negocio.telefone_admin).slice(-8));

if (ehEntregador || ehDono) {
  // Numero de entregador/dono mandando texto com cara de resposta do proprio bot: eco confirmado, descarta.
  return [];
}

return [{ json: negocio }];

const d = $('Extrair Coordenadas').first().json;

const headers = {
  apikey: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNsY3l5b2d0dnlncGVoZ2NtZXlqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4MDA4NTQ3NCwiZXhwIjoyMDk1NjYxNDc0fQ.XizutisZ4syhlUMlTRisVg1J8jFNNrZ9bF54ntF4B4M',
  Authorization: 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNsY3l5b2d0dnlncGVoZ2NtZXlqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4MDA4NTQ3NCwiZXhwIjoyMDk1NjYxNDc0fQ.XizutisZ4syhlUMlTRisVg1J8jFNNrZ9bF54ntF4B4M',
  'Content-Type': 'application/json',
};

let existente = null;
try {
  const rows = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://clcyyogtvygpehgcmeyj.supabase.co/rest/v1/dados_clientes_gas?negocio_id=eq.' + d.negocio_id + '&remote_jid=eq.' + encodeURIComponent(d.remoteJid) + '&select=total_pedidos,produtos_ja_comprados',
    headers,
    json: true,
  });
  existente = Array.isArray(rows) && rows.length ? rows[0] : null;
} catch (e) {}

const totalAnterior = existente?.total_pedidos ?? 0;
const produtosAnteriores = Array.isArray(existente?.produtos_ja_comprados) ? existente.produtos_ja_comprados : [];
const produtosAtualizados = d.produto ? [...produtosAnteriores, d.produto] : produtosAnteriores;

const cepMatch = (d.endereco || '').match(/\d{5}-?\d{3}/);

const payload = {
  negocio_id: d.negocio_id,
  remote_jid: d.remoteJid,
  cliente_telefone: d.remoteJid,
  nome: d.nome_cliente || d.pushName,
  ultimo_endereco: d.endereco || null,
  ultimo_cep: cepMatch ? cepMatch[0] : null,
  data_ultima_compra: new Date().toISOString(),
  produtos_ja_comprados: produtosAtualizados,
  total_pedidos: totalAnterior + 1,
};

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://clcyyogtvygpehgcmeyj.supabase.co/rest/v1/dados_clientes_gas?on_conflict=negocio_id,remote_jid',
    headers: { ...headers, Prefer: 'resolution=merge-duplicates' },
    body: payload,
    json: true,
  });
} catch (e) {
  // nao bloqueia o fluxo principal (pedido ja foi salvo e entregador ja foi notificado antes deste node)
}

return [{ json: d }];

const filtro = $('Filtrar e Extrair').first().json;
const negocio = $('Carregar Dados Negocio').first().json;

const resposta = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://clcyyogtvygpehgcmeyj.supabase.co/rest/v1/pedidos_gas?negocio_id=eq.' + negocio.id + '&cliente_telefone=eq.' + encodeURIComponent(filtro.remoteJid) + '&select=status,eta_estimado_texto,produto_nome,criado_em&order=criado_em.desc&limit=1',
  headers: {
    apikey: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNsY3l5b2d0dnlncGVoZ2NtZXlqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4MDA4NTQ3NCwiZXhwIjoyMDk1NjYxNDc0fQ.XizutisZ4syhlUMlTRisVg1J8jFNNrZ9bF54ntF4B4M',
    Authorization: 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNsY3l5b2d0dnlncGVoZ2NtZXlqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4MDA4NTQ3NCwiZXhwIjoyMDk1NjYxNDc0fQ.XizutisZ4syhlUMlTRisVg1J8jFNNrZ9bF54ntF4B4M',
  },
  json: true,
});

if (!Array.isArray(resposta) || resposta.length === 0) {
  return JSON.stringify({ encontrado: false });
}

return JSON.stringify({ encontrado: true, ...resposta[0] });

// Decide audio (com preferencia pegajosa por conversa) - sem sorteio, so decisao explicita ou preferencia salva
const dados = $('Processar Resposta Agent').first().json;
const output = dados.resposta_limpa || '';

const msgClienteBruta = $('Montar Contexto').first().json.mensagem || '';
const prefereAudioAtual = $('Montar Contexto').first().json.prefere_audio_efetivo ?? false;

// Remove acentos antes de comparar - "áudio" nao bate em .includes('audio') sem isso
function normalizar(s) {
  return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
const msgCliente = normalizar(msgClienteBruta);

// Cliente mandou a mensagem em audio (independente do que falou) -> responde em audio automaticamente
