  msgCliente.includes('voz') ||
  msgCliente.includes('me fala') ||
  msgCliente.includes('manda um audio') ||
  msgCliente.includes('responde em audio') ||
  msgCliente.includes('pode mandar audio') ||
  msgCliente.includes('nao consigo ler') ||
